<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Dashboard</h1><p class="text-muted mb-0">Your real-time expense overview.</p></div><a href="<?=url('expenses/create')?>" class="btn btn-primary"><i data-feather="plus" class="me-1"></i>Add Expense</a></div><div class="row"><div class="col-xl-3 col-sm-6"><div class="card"><div class="card-body"><div class="text-muted">Total Expenses</div><div class="stat-value"><?=money($stats['total'])?></div></div></div></div><div class="col-xl-3 col-sm-6"><div class="card"><div class="card-body"><div class="text-muted">This Month</div><div class="stat-value"><?=money($stats['month'])?></div></div></div></div><div class="col-xl-3 col-sm-6"><div class="card"><div class="card-body"><div class="text-muted">Today's Expenses</div><div class="stat-value"><?=money($stats['today'])?></div></div></div></div><div class="col-xl-3 col-sm-6"><div class="card"><div class="card-body"><div class="text-muted">Accounts Balance</div><div class="stat-value"><?=money($stats['balance'])?></div></div></div></div></div><div class="row"><div class="col-xl-8"><div class="card"><div class="card-header"><h5 class="card-title mb-0">Monthly Expenses</h5></div><div class="card-body"><canvas id="monthlyChart" height="120"></canvas></div></div></div><div class="col-xl-4"><div class="card"><div class="card-header"><h5 class="card-title mb-0">Expense by Category</h5></div><div class="card-body"><canvas id="categoryChart" height="250"></canvas></div></div></div></div><div class="row"><div class="col-md-6"><div class="card"><div class="card-body"><div class="d-flex justify-content-between"><div><div class="text-muted">Current Budget</div><div class="h4 mb-0"><?=money($stats['budget'])?></div></div><div class="text-end"><div class="text-muted">Remaining</div><div class="h4 mb-0 <?=($stats['remaining']<0?'text-danger':'')?>"><?=money($stats['remaining'])?></div></div></div><?php $pct=$stats['budget']>0?min(100,max(0,($stats['month']/$stats['budget'])*100)):0; ?><div class="progress mt-3" style="height:8px"><div class="progress-bar <?=($pct>=100?'bg-danger':($pct>=90?'bg-warning':''))?>" style="width:<?=$pct?>%"></div></div></div></div></div></div><?php $scripts='<script>const monthly='.json_encode($stats['monthly']).'; const cats='.json_encode($stats['byCategory']).'; const mc=document.getElementById("monthlyChart"); new Chart(mc,{type:"line",data:{labels:monthly.map(x=>x.label),datasets:[{label:"Expenses",data:monthly.map(x=>Number(x.value)),fill:false}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}}); const cc=document.getElementById("categoryChart"); new Chart(cc,{type:"doughnut",data:{labels:cats.map(x=>x.label),datasets:[{data:cats.map(x=>Number(x.value))}]},options:{responsive:true,plugins:{legend:{position:"bottom"}}}});</script>'; ?>